class DecryptionUtils:
    A_OFFSET = 65
    Z_OFFSET = 97
    ALPHABET_SIZE = 26
    A_CHAR = 'a'
    Z_CHAR = 'z'

    def __init__(self, key):
        self._key = key

    @property
    def key(self):
        return self._key

    def caesar_decipher(self, ciphertext, shift):
        plaintext = self._transform_caesar(ciphertext, shift)
        return plaintext

    def _transform_caesar(self, ciphertext, shift):
        plaintext = ""
        for char in ciphertext:
            if char.isalpha():
                ascii_offset = self.A_OFFSET if char.isupper() else self.Z_OFFSET
                shifted_char = self._shift_char(char, ascii_offset, shift)
                plaintext += shifted_char
            else:
                plaintext += char
        return plaintext

    def _shift_char(self, char, ascii_offset, shift):
        return chr((ord(char) - ascii_offset - shift) % self.ALPHABET_SIZE + ascii_offset)

    def vigenere_decipher(self, ciphertext):
        decrypted_text = self._process_vigenere(ciphertext)
        return decrypted_text

    def _process_vigenere(self, ciphertext):
        decrypted_text = ""
        key_index = 0
        for char in ciphertext:
            if char.isalpha():
                shift = self._get_vigenere_shift(key_index)
                decrypted_char = self._decrypt_vigenere_char(char, shift)
                decrypted_text += decrypted_char
                key_index += 1
            else:
                decrypted_text += char
        return decrypted_text

    def _get_vigenere_shift(self, key_index):
        return ord(self.key[key_index % len(self.key)].lower()) - ord(self.A_CHAR)

    def _decrypt_vigenere_char(self, char, shift):
        base_char = char.lower()
        decrypted_char = chr((ord(base_char) - ord(self.A_CHAR) - shift) % self.ALPHABET_SIZE + ord(self.A_CHAR))
        return decrypted_char.upper() if char.isupper() else decrypted_char

    def rail_fence_decipher(self, encrypted_text, rails):
        if rails <= 1:
            return encrypted_text
        if rails >= len(encrypted_text):
            return encrypted_text[::-1] if rails == len(encrypted_text) else encrypted_text

        fence = self._build_rail_fence_structure(encrypted_text, rails)
        self._fill_rail_fence(fence, encrypted_text)
        plain_text = self._read_rail_fence(fence, encrypted_text, rails)
        return plain_text

    def _build_rail_fence_structure(self, encrypted_text, rails):
        fence = [['\n' for _ in range(len(encrypted_text))] for _ in range(rails)]
        direction = -1
        row, col = 0, 0

        for _ in range(len(encrypted_text)):
            if row == 0 or row == rails - 1:
                direction = -direction

            fence[row][col] = ''
            col += 1
            row += direction

        return fence

    def _fill_rail_fence(self, fence, encrypted_text):
        index = 0
        for i in range(len(fence)):
            for j in range(len(fence[i])):
                if fence[i][j] == '':
                    fence[i][j] = encrypted_text[index]
                    index += 1

    def _read_rail_fence(self, fence, encrypted_text, rails):
        plain_text = ''
        direction = -1
        row, col = 0, 0
        for _ in range(len(encrypted_text)):
            if row == 0 or row == rails - 1:
                direction = -direction

            plain_text += fence[row][col]
            col += 1
            row += direction

        return plain_text
